INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Oprah Winfrey win the 2028 Democratic presidential nomination?', 'This market will resolve to “Yes” if the named individual wins and accepts the 2028 nomination of the Democratic Party for U.S. president. Otherwise, this market will resolve to “No”. The resolution source for this market will be a consensus of official Democratic Party sources. Any replacement of the democratic nominee before election day will not change the resolution of the market.', 'politics', 'active', 271151.09, 26843958.02, 271651.09, 26844458.02);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Byron Donalds win the 2028 Republican presidential nomination?', 'This market will resolve to “Yes” if the named individual wins and accepts the 2028 nomination of the Republican Party for U.S. president. Otherwise, this market will resolve to “No”. The resolution source for this market will be a consensus of official Republican Party sources. Any replacement of the Republican nominee before election day will not change the resolution of the market.', 'politics', 'active', 221903.64, 21968460.15, 222403.64, 21968960.15);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will LeBron James win the 2028 US Presidential Election?', 'The 2028 US Presidential Election is scheduled to take place on November 7, 2028. This market will resolve to the person who wins the 2028 US Presidential Election. The resolution source for this market is the Associated Press, Fox News, and NBC. This market will resolve once all three sources call the race for the same candidate. If all three sources haven’t called the race for the same candidate by the inauguration date (January 20, 2029) this market will resolve based on who is inaugurated.', 'politics', 'active', 272516.71, 26979154.08, 273016.71, 26979654.08);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Adanech Abiebie be the next Prime Minister of Ethiopia?', 'General elections are scheduled to be held in Ethiopia on June 1, 2026. This market will resolve to the next individual who officially assumes the office of Prime Minister of Ethiopia following the 2026 General elections. To count for resolution, the individual must be officially appointed and sworn in as Prime Minister of Ethiopia. Any interim or caretaker Prime Minister will not count toward the resolution of this market. If no such Prime Minister takes office by December 31, 2028, 11:59 PM ET', 'politics', 'active', 390376.43, 38647266.99, 390876.43, 38647766.99);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Oliver Bearman be the 2026 F1 Drivers'' Champion?', 'This market will resolve according to the listed driver that finishes 1st in the driver standings for the 2026 F1 season. This market will resolve as soon as the official results of the final scheduled race of the 2026 F1 season are known. If multiple drivers tie for first place in the drivers standings, this market will resolve according to the tiebreak procedure used by F1 to determine the 2026 F1 Drivers’ champion. If at any point it becomes impossible for a listed driver to win the 2026 F1 D', 'sports', 'active', 64425.21, 6378096.23, 64925.21, 6378596.23);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Netanyahu out by end of 2026?', 'This market will resolve to “Yes” if Benjamin Netanyahu ceases to be Prime Minister of Israel for any period of time between market creation and the specified date (ET). Otherwise, this market will resolve to “No”. An announcement of Benjamin Netanyahu''s resignation/removal before this market''s end date will immediately resolve this market to "Yes", regardless of when the announced resignation/removal goes into effect. The resolution source for this market will be official information from Ben', 'politics', 'active', 448745.18, 607125.84, 449245.18, 607625.84);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Tarcisio de Freitas win the 2026 Brazilian presidential election?', 'A presidential election is scheduled to take place in Brazil on October 4, 2026. This market will resolve according to the listed candidate that wins this election. This market includes any potential second round. If the result of this election isn''t known by June 30, 2027, 11:59 PM ET, the market will resolve to "Other". This market will resolve based on the result of the election as indicated by a consensus of credible reporting. If there is ambiguity, this market will resolve based solely on', 'politics', 'active', 69552.95, 6885741.92, 70052.95, 6886241.92);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Mathilde Panot win the 2027 French presidential election?', 'The next French presidential election is currently expected to be held around April 2027. This market pertains to the outcome of the next French presidential election, regardless of whether it follows the scheduled end of the current term or is held earlier. The President of France is elected via a two-round system; a candidate must secure over 50% of the vote to win outright in the first round. If no candidate achieves this, the top two contenders advance to a runoff. This market will resolve a', 'politics', 'active', 31372.81, 3105908.02, 31872.81, 3106408.02);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Richard Grenell be the leader of Venezuela end of 2026?', 'This market will resolve to the individual who officially holds the position of the head of state of Venezuela on Dec 31, 2026 at 12 PM ET. For the purposes of this market, "officially holds" refers to the individual that was formally appointed, confirmed (if confirmation is required), and sworn in as the head of state of Venezuela or otherwise confirmed by official government information as being the head of state of Venezuela. If the Venezuelan government does not clearly state who is the head', 'politics', 'active', 163191.29, 16155937.67, 163691.29, 16156437.67);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Kharg Island no longer under Iranian control by August 31?', 'This market will resolve to "Yes" if Kharg Island is no longer under Iranian control by August 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". “No longer under the control of Iran” means that Iran no longer exercises primary governmental or military control over Kharg Island, and another state, occupying force, or internationally backed authority has established control over the island. Temporary raids, isolated landings, special operations, bombardment, sabotage, naval prese', 'politics', 'active', 38062.93, 2200933.18, 38562.93, 2201433.18);